import {BUILTIN,MUSCLES,muscleName,matchExercises,normalize} from './catalog.js';
import {uid,initialState,loadState,storeState,backupActive,readActiveBackup,normalizeLoaded,formatDuration,sessionSeconds,dateLabel,dateKey,num,doneSets,setVolume,volumeOf,sessionVolume,previousExecution,exerciseHistory,exportCSV} from './data.js';
import {anatomySVG} from './anatomy.js';

let state=initialState(),page='home',modal=null,selectedDay=null,historyDate=null,historySessionId=null,progressExercise=null,progressGym='current',progressMetric='weight',progressPeriod='90',musclePeriod='7',muscleGym='all',muscleFocus=null,sessionSummary=false;
let saveTimeout=null,saveChain=Promise.resolve(),toastTimeout=null;
const app=document.getElementById('app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dval=v=>Number.isFinite(v)?Number(v.toFixed(1)).toLocaleString('it-IT'):"0";
const shortDate=ms=>new Intl.DateTimeFormat('it-IT',{day:'numeric',month:'short'}).format(new Date(ms));
const weekday=ms=>new Intl.DateTimeFormat('it-IT',{weekday:'long'}).format(new Date(ms));
const $ex=id=>[...BUILTIN,...state.customExercises].find(e=>e.id===id);
const gymName=id=>state.gyms.find(g=>g.id===id)?.name||'Palestra';
const $program=()=>state.programs.find(p=>p.id===state.programId)||state.programs[0]||null;
const $day=()=>($program()?.days||[]).find(d=>d.id===selectedDay)||$program()?.days?.[0]||null;
const assignments=(day,gymId=state.gymId)=>(day?.byGym||{})[gymId]||[];
const $entry=id=>state.active?.entries.find(e=>e.id===id);
const $set=(entryId,setId)=>$entry(entryId)?.sets.find(s=>s.id===setId);
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',dumbbell:'<path d="m6.5 6.5 11 11M4 4l4 4M2 6l4-4M16 20l4-4M18 22l4-4"/>',chart:'<path d="M4 20V10m6 10V4m6 16v-7m4 7v-12"/>',history:'<path d="M3 12a9 9 0 1 0 2.6-6.4L3 8m0-5v5h5m4-1v5l4 2"/>',activity:'<path d="M22 12h-4l-3 8L9 4l-3 8H2"/>',settings:'<path d="M12 15.2a3.2 3.2 0 1 0 0-6.4 3.2 3.2 0 0 0 0 6.4ZM19.4 15.5l1.4 1.1-2 3.4-1.7-.6a8.7 8.7 0 0 1-2.1 1.2l-.3 1.9h-4l-.4-1.9a8 8 0 0 1-2-1.2l-1.8.6-2-3.4L6 15.5a7 7 0 0 1 0-2.5l-1.5-1.2 2-3.3 1.8.5a9 9 0 0 1 2-1.1l.4-1.9h4l.3 1.9a9 9 0 0 1 2.1 1.1l1.7-.5 2 3.3-1.4 1.2a7 7 0 0 1 0 2.5Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',back:'<path d="m15 18-6-6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',trophy:'<path d="M7 3h10v7a5 5 0 0 1-10 0V3Zm10 2h4v3a4 4 0 0 1-4 4M7 5H3v3a4 4 0 0 0 4 4m5 3v5m-4 0h8"/>',edit:'<path d="m4 20 4-1 11-11-3-3L5 16l-1 4Zm10-13 3 3"/>',swap:'<path d="M4 7h16l-4-4m4 4-4 4M20 17H4l4-4m-4 4 4 4"/>',trash:'<path d="M4 7h16m-13 0 1 14h8l1-14M9 7V4h6v3"/>',up:'<path d="M12 20V4m-7 7 7-7 7 7"/>',down:'<path d="M12 4v16m-7-7 7 7 7-7"/>',pause:'<path d="M8 5v14m8-14v14"/>',play:'<path d="m8 5 12 7-12 7z"/>',save:'<path d="M4 4h14l2 2v14H4V4Zm3 0v6h10V4M7 20v-8h10v8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 18v3h16v-3"/>',upload:'<path d="M12 20V8m-5 5 5-5 5 5M4 6V3h16v3"/>',file:'<path d="M6 3h9l4 4v14H6zM15 3v5h4"/>',chev:'<path d="m7 10 5 5 5-5"/>',close:'<path d="M5 5l14 14M19 5 5 19"/>',spark:'<path d="m12 2 2.3 7.7L22 12l-7.7 2.3L12 22l-2.3-7.7L2 12l7.7-2.3L12 2Z"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5Zm-9 9 9 5 9-5m-18 5 9 5 9-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',folder:'<path d="M3 6h7l2 2h9v12H3z"/>'};
function ic(name,size=18){return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.info}</svg>`;}
const btn=(text,action,opts={})=>`<button type="button" class="btn ${opts.kind||''} ${opts.size||''} ${opts.full?'full':''}" data-action="${action}" ${Object.entries(opts.data||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')} ${opts.disabled?'disabled':''}>${opts.icon?ic(opts.icon,16):''}${text}</button>`;
const tag=(text,type='')=>`<span class="pill ${type}">${text}</span>`;
const field=(label,value,bind,props={})=>`<div class="field ${props.compact?'compact':''}"><label>${label}</label><input class="input" type="${props.type||'text'}" ${props.min!==undefined?`min="${props.min}"`:''} ${props.step?`step="${props.step}"`:''} placeholder="${esc(props.placeholder||'')}" value="${esc(value??'')}" data-bind="${bind}" ${Object.entries(props.data||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')} /></div>`;
const options=(arr,value)=>arr.map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('');
const select=(arr,val,bind,props={})=>`<select class="select" data-bind="${bind}" ${Object.entries(props.data||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${options(arr,val)}</select>`;
const exerciseOptions=()=>[...BUILTIN,...state.customExercises];
const muscleOptions=()=>MUSCLES.map(m=>({value:m[0],label:m[1]}));
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),3200);}
function persist(immediate=false){state.updatedAt=Date.now();if(state.active){state.active.updatedAt=state.updatedAt;backupActive(state.active,state.customExercises);}const snapshot=structuredClone(state);if(saveTimeout)clearTimeout(saveTimeout);if(immediate){commit(snapshot);return;}saveTimeout=setTimeout(()=>commit(structuredClone(state)),160);}
function commit(snapshot){saveTimeout=null;const write=saveChain.catch(()=>{}).then(()=>storeState(snapshot));saveChain=write.catch(err=>{console.error(err);toast('Problema di salvataggio. Esporta un backup appena possibile.');});return write;}
function redraw({top=false}={}){const y=window.scrollY;const old=app.querySelector('.overlay');const oldScroll=old?.querySelector('.search-results')?.scrollTop||0;app.innerHTML=layout();if(modal){const newList=app.querySelector('.search-results');if(newList)newList.scrollTop=oldScroll;}if(top)window.scrollTo(0,0);else window.scrollTo(0,y);}
function navigate(dest){page=dest;modal=null;sessionSummary=false;redraw({top:true});}
function head(title,sub,right=''){return `<header class="page-head"><div><div class="eyebrow">REP<span style="text-transform:none">z</span> · Train. Track. Progress.</div><h1>${esc(title)}</h1>${sub?`<p class="sub">${sub}</p>`:''}</div>${right}</header>`;}
function nav(){const tabs=[['home','home','Home'],['plans','dumbbell','Schede'],['workout','play','Allenamento'],['history','history','Storico'],['progress','chart','Progressi'],['checkup','activity','Check-up']];return `<nav class="sticky-nav" aria-label="Navigazione principale">${tabs.map(([id,i,label])=>`<button type="button" class="nav-btn ${page===id||page==='finish'&&id==='workout'?'active':''}" data-action="go" data-to="${id}"><span class="nav-ico">${ic(i,22)}</span><strong>${label}</strong></button>`).join('')}</nav>`;}
function layout(){return `<div class="app-shell">${page==='home'?homeView():page==='plans'?plansView():page==='workout'?workoutView():page==='finish'?finishView():page==='history'?historyView():page==='progress'?progressView():page==='checkup'?checkupView():page==='settings'?settingsView():homeView()}<div class="footer-note">REPz · I tuoi dati rimangono sul tuo dispositivo</div></div>${nav()}${modal?modalView():''}`;}
function emptyBlock(icon,title,description,button){return `<div class="card empty"><div class="big">${icon}</div><h2>${title}</h2><p class="sub" style="margin:8px auto 18px;max-width:310px">${description}</p>${button||''}</div>`;}
function gymSelector(){return `<div class="card"><div class="row between mb12"><div class="row"><span style="color:#83b7ff">${ic('pin',18)}</span><b>Palestra attiva</b></div>${btn('Gestisci','go',{size:'small',kind:'link',data:{to:'settings'}})}</div><div class="gym-grid">${state.gyms.map(g=>`<button class="gym-choice ${state.gymId===g.id?'selected':''}" data-action="choose-gym" data-id="${g.id}">${ic(state.gymId===g.id?'check':'pin',19)}<strong>${esc(g.name)}</strong></button>`).join('')}</div></div>`;}
function nextDay(p){if(!p?.days?.length)return null;return p.days.find(d=>d.id===p.nextDayId)||p.days[0];}
function recentSessions(){return [...state.sessions].sort((a,b)=>b.startedAt-a.startedAt);}
function homeView(){const p=$program(),next=nextDay(p),recent=recentSessions(),weekly=recent.filter(s=>Date.now()-s.startedAt<7*864e5);return `${head('La tua dashboard','Allenati, registra, migliora.',`<button class="btn secondary icon-btn" title="Impostazioni" data-action="go" data-to="settings">${ic('settings',20)}</button>`)}
${state.active?`<div class="card soft"><div class="row between"><div><span class="eyebrow">SESSIONE ATTIVA</span><h2>${esc(state.active.dayName)}</h2><p class="sub">${esc(gymName(state.active.gymId))} · <span class="live-duration">${formatDuration(sessionSeconds(state.active))}</span></p></div>${ic('clock',27)}</div>${btn('Riprendi allenamento','go',{data:{to:'workout'},full:true,icon:'play'})}</div>`:''}
${gymSelector()}
${!p?emptyBlock('🏋️','La tua prima scheda','Nessuna scheda predefinita. Costruisci liberamente giorni ed esercizi per ciascuna palestra.',btn('Crea scheda','new-program',{full:true,icon:'plus'})):
`<div class="section-head"><h2>Prossimo allenamento</h2>${tag(esc(p.name),'highlight')}</div>${next?`<div class="card"><div class="eyebrow">SEQUENZA CONSIGLIATA</div><h2 style="font-size:23px;margin-top:8px">${esc(next.name)}</h2><p class="sub">${esc(next.focus||'Distretti a tua scelta')}</p><div class="divider"></div><p class="small muted">${assignments(next).length} esercizi nella ${esc(gymName(state.gymId))}</p><div class="row mt12">${btn(p.archived?'Scheda archiviata':'Inizia allenamento','start-day',{full:true,icon:'play',disabled:!!p.archived,data:{id:next.id}})}${btn('Schede','go',{kind:'secondary',data:{to:'plans'}})}</div></div>`:emptyBlock('📝','Aggiungi il primo giorno','La scheda è vuota. Crea Giorno 1 e scegli gli esercizi.',btn('Apri scheda','go',{data:{to:'plans'}}))}`}
<div class="section-head"><h2>Ultimi 7 giorni</h2>${btn('Storico','go',{kind:'link',size:'small',data:{to:'history'}})}</div><div class="stat-grid"><div class="stat"><div class="stat-label">Sedute registrate</div><div class="stat-num">${weekly.length}</div></div><div class="stat"><div class="stat-label">Tempo totale</div><div class="stat-num">${Math.floor(weekly.reduce((v,s)=>v+sessionSeconds(s),0)/3600)}h ${Math.floor(weekly.reduce((v,s)=>v+sessionSeconds(s),0)%3600/60)}m</div></div></div>
${recent[0]?`<div class="section-head"><h2>Ultima seduta</h2></div><div class="card"><div class="row between"><div><b>${esc(recent[0].dayName)}</b><p class="sub">${esc(gymName(recent[0].gymId))} · ${dateLabel(recent[0].startedAt)}</p></div>${tag(recent[0].status==='partial'?'Parziale':'Completata',recent[0].status==='partial'?'warn':'success')}</div><div class="row mt12">${btn('Apri dettagli','session-detail',{kind:'ghost',size:'small',data:{id:recent[0].id}})}${btn('Check-up','go',{kind:'secondary',size:'small',data:{to:'checkup'}})}</div></div>`:''}`;}
function plansView(){const p=$program(),days=p?.days||[],d=$day(),list=assignments(d);return `${head('Le mie schede','Crea programmi, giorni ed esercizi.',btn('Impostazioni','go',{kind:'secondary',size:'small',data:{to:'settings'}}))}
<div class="card"><div class="row between"><b>Programma attivo</b>${btn('Nuovo','new-program',{kind:'secondary',size:'small',icon:'plus'})}</div>${state.programs.length?`<div class="mt12">${select(state.programs.map(v=>({value:v.id,label:v.name+(v.archived?' (archiviata)':'')})),p?.id,'program-select')}</div><div class="row mt12">${btn(p.archived?'Ripristina scheda':'Archivia scheda','archive-program',{kind:'ghost',size:'small',icon:'folder'})}${btn('Rinomina','rename-program',{kind:'ghost',size:'small',icon:'edit'})}${btn('Elimina','delete-program',{kind:'danger',size:'small',icon:'trash'})}</div>`:'<p class="sub">Nessun programma creato.</p>'}</div>
${!p?emptyBlock('📋','Crea la tua scheda','Non ci sono programmi predefiniti.',btn('Crea scheda','new-program',{icon:'plus',full:true})):
`<div class="section-head"><h2>Giorni della scheda</h2>${btn('Aggiungi giorno','new-day',{kind:'secondary',size:'small',icon:'plus'})}</div>
${days.length?`<div class="tab-pills">${days.map(x=>btn(esc(x.name),'choose-day',{kind:d?.id===x.id?'':'secondary',size:'small',data:{id:x.id}})).join('')}</div>`:emptyBlock('📅','Nessun giorno creato','Aggiungi Giorno 1, Giorno 2 e tutti i giorni che desideri.',btn('Aggiungi giorno','new-day',{icon:'plus',full:true}))}
${d?`<div class="card"><div class="row between"><div><h2>${esc(d.name)}</h2><p class="sub">${esc(d.focus||'Distretti da impostare')}</p></div>${btn('Modifica','edit-day',{size:'small',kind:'secondary',icon:'edit'})}</div><div class="row mt12">${btn('Inizia questo giorno','start-day',{icon:'play',disabled:!!p.archived,data:{id:d.id}})}${btn('Elimina giorno','delete-day',{kind:'danger',size:'small'})}</div></div>
<div class="card flat"><div class="row between"><span class="eyebrow">ESERCIZI PER PALESTRA</span>${tag(esc(gymName(state.gymId)),'highlight')}</div><div class="tab-pills mt12">${state.gyms.map(g=>btn(esc(g.name),'choose-gym',{kind:state.gymId===g.id?'':'secondary',size:'small',data:{id:g.id}})).join('')}</div><div class="row wrap">${btn('Copia da altra palestra','copy-day',{kind:'ghost',size:'small',icon:'layers'})}</div></div>
${list.map((a,i)=>{const ex=$ex(a.exerciseId);return `<div class="card"><div class="row between"><div class="row grow"><div class="icon-circle">${ic('dumbbell',19)}</div><div class="grow"><b>${i+1}. ${esc(a.label||ex?.name||'Esercizio sconosciuto')}</b><p class="sub">${a.setCount} serie · ${esc(a.targetMin)}–${esc(a.targetMax)} rep · RIR ${esc(a.targetRir)} · ${esc(a.restSec)} s</p><p class="tiny muted">${esc(muscleName(ex?.primary||'')||'')} ${a.unilateral?'· Unilaterale':''}</p></div></div></div><div class="row wrap mt12">${btn('Configura','config-assignment',{kind:'secondary',size:'small',icon:'edit',data:{id:a.id}})}${btn('Sostituisci','browse-catalog',{kind:'ghost',size:'small',icon:'swap',data:{mode:'plan-replace',id:a.id}})}${btn('↑','move-assignment',{kind:'ghost',size:'small',data:{id:a.id,delta:-1},disabled:i===0})}${btn('↓','move-assignment',{kind:'ghost',size:'small',data:{id:a.id,delta:1},disabled:i===list.length-1})}${btn('Elimina','remove-assignment',{kind:'danger',size:'small',data:{id:a.id}})}</div></div>`;}).join('')}
${btn('Aggiungi esercizio','browse-catalog',{kind:'outline-dashed',full:true,icon:'plus',data:{mode:'plan-add'}})}`:''}`}`;}
function makeSet(){return {id:uid('set'),kg:'',reps:'',rir:'',kgL:'',kgR:'',repsL:'',repsR:'',rirL:'',rirR:'',done:false,technique:'normal',failure:false};}
function makeEntry(exercise,assignment=null,extra=false){const n=assignment?.setCount||3;return {id:uid('ent'),exerciseId:exercise.id,name:assignment?.label?.trim()||exercise.name,originalId:null,originalName:'',plannedAssignmentId:assignment?.id||null,extra,sets:Array.from({length:n},makeSet),feedback:'',restSec:assignment?.restSec??state.settings.restDefault,supersetGroup:assignment?.supersetGroup||'',unilateral:assignment?.unilateral??false,targetMin:assignment?.targetMin??8,targetMax:assignment?.targetMax??12,targetRir:assignment?.targetRir??2,expanded:true};}
function beginWorkout(dayId){if(state.active){navigate('workout');toast('Hai già un allenamento in corso.');return;}const p=$program();const day=p?.days?.find(d=>d.id===dayId);if(!day){toast('Seleziona prima un giorno della scheda.');return;}if(p.archived){toast('La scheda è archiviata. Ripristinala prima di allenarti.');return;}const gym=state.gymId;const entries=assignments(day,gym).map((a,i)=>({...makeEntry($ex(a.exerciseId)||{id:a.exerciseId,name:'Esercizio non trovato'},a),expanded:i===0}));const newSession={id:uid('session'),programId:p.id,programName:p.name,dayId:day.id,dayName:day.name,focus:day.focus||'',gymId:gym,gymName:gymName(gym),startedAt:Date.now(),pausedAt:null,pausedMs:0,endedAt:null,status:'active',entries,note:'',expandedId:entries[0]?.id||null,scrollY:0,restTimer:null,updatedAt:Date.now()};state.active=newSession;persist(true);navigate('workout');toast('Allenamento avviato e salvataggio automatico attivo.');}
function workoutView(){const s=state.active;if(!s)return `${head('Allenamento','Nessuna seduta attiva.')}${emptyBlock('🏋️','Nessun allenamento in corso','Apri una scheda e premi Inizia allenamento.',btn('Vai alle schede','go',{data:{to:'plans'},full:true}))}`;
const count=s.entries.reduce((v,e)=>v+doneSets(e).length,0),tot=s.entries.reduce((v,e)=>v+e.sets.length,0);return `<div class="session-banner"><div class="split-title"><div><div class="eyebrow">ALLENAMENTO IN CORSO</div><h2>${esc(s.dayName)}</h2><p class="sub">${esc(gymName(s.gymId))} · ${esc(s.focus||'Allenamento libero')}</p></div><div class="session-time ${s.pausedAt?'paused':''}">${ic('clock',14)} <span class="live-duration">${formatDuration(sessionSeconds(s))}</span></div></div><div class="row between mt8"><span class="sub">${count}/${tot} serie completate</span>${btn(s.pausedAt?'Riprendi':'Pausa',s.pausedAt?'resume-session':'pause-session',{size:'xs',kind:'secondary',icon:s.pausedAt?'play':'pause'})}</div><div class="progress-track mt8"><div class="progress-fill" style="width:${tot?count/tot*100:0}%"></div></div></div>
${s.pausedAt?'<div class="inline-alert mb16">⏸ Allenamento in pausa. Puoi riprenderlo in qualsiasi momento.</div>':''}
${s.entries.length?s.entries.map((e,i)=>`<div id="entry-${esc(e.id)}" class="scroll-restore">${exerciseCard(e,i,s)}<div class="insert-line">${btn('Aggiungi esercizio','browse-catalog',{kind:'ghost',size:'small',icon:'plus',data:{mode:'session-insert',index:i}})}</div></div>`).join(''):
`<div class="card empty"><div class="big">➕</div><h2>Allenamento vuoto</h2><p class="sub">Aggiungi gli esercizi che vuoi svolgere oggi.</p></div>${btn('Aggiungi esercizio','browse-catalog',{kind:'ghost',full:true,icon:'plus',data:{mode:'session-insert',index:-1}})}`}
<div class="card"><div class="row mb12">${ic('edit',20)}<h3>Feedback finale ed esercizi extra</h3></div><textarea class="textarea" data-bind="session-note" placeholder="Sensazioni generali, energia, esercizi extra, macchine occupate...">${esc(s.note)}</textarea><p class="sub tiny mt8">Gli extra aggiunti come card contribuiscono a grafici e statistiche; ciò che scrivi qui rimane una nota.</p></div>
${btn('Termina allenamento','show-finish',{full:true,icon:'check'})}<p class="footer-note">La sessione viene salvata automaticamente mentre scrivi.</p>`;}
function exerciseCard(e,i,s){const ex=$ex(e.exerciseId),expanded=e.expanded!==false,prev=previousExecution(state,e.exerciseId,s.gymId,s.id);const count=doneSets(e).length;const last=prev?.entry;const lastSets=last?doneSets(last):[];const progHint=lastSets.length&&e.targetMax?progressHint(e,lastSets):'';
return `<article class="card exercise-card"><div class="exercise-head"><div class="icon-circle">${ic('dumbbell',20)}</div><button class="exercise-head-title" data-action="toggle-entry" data-id="${e.id}"><span>${i+1}. ${esc(e.name)}</span><div class="pills mt8">${e.extra?tag('EXTRA','highlight'):''}${e.originalName?tag('Sostituisce: '+esc(e.originalName)):''}${e.unilateral?tag('Unilaterale'):''}${e.supersetGroup?tag('Superset '+esc(e.supersetGroup),'highlight'):''}${count===e.sets.length&&count?tag('Completato','success'):tag(`${count}/${e.sets.length} serie`)}</div></button><button class="btn link icon-btn" data-action="toggle-entry" data-id="${e.id}" aria-label="${expanded?'Comprimi':'Apri'} esercizio">${ic(expanded?'up':'down',17)}</button></div>
${expanded?`${prev?`<div class="previous"><div class="row between"><span class="eyebrow">${ic('history',13)} ULTIMA ESECUZIONE</span><span class="sub tiny">${esc(dateLabel(prev.session.startedAt))}</span></div>${last.unilateral?`<div class="small mt8">${lastSets.map((x,j)=>`<div class="row between" style="padding:4px 0"><span class="muted">Serie ${j+1}</span><span>SX: ${esc(x.kgL||'-')} kg × ${esc(x.repsL||'-')}</span><span>DX: ${esc(x.kgR||'-')} kg × ${esc(x.repsR||'-')}</span></div>`).join('')}</div>`:
`<table class="prev-table">${lastSets.map((x,j)=>`<tr><td>Serie ${j+1}</td><td>${esc(x.kg)} kg</td><td>${esc(x.reps)} rep</td><td>RIR ${esc(x.rir||'–')}</td></tr>`).join('')}</table>`}
<div class="divider"></div><div class="tiny muted">FEEDBACK PRECEDENTE</div><p class="small feedback-copy">${last.feedback?esc(last.feedback):'<span class="muted">Nessun feedback salvato</span>'}</p></div>`:`<div class="previous"><span class="sub">Prima esecuzione registrata in questa palestra. Lo storico partirà da oggi.</span></div>`}
<div class="row between mt12"><span class="small muted">Obiettivo: ${esc(e.targetMin)}–${esc(e.targetMax)} rep · RIR ${esc(e.targetRir)}</span>${btn(e.unilateral?'Unilaterale ✓':'Modalità unilaterale','toggle-unilateral',{kind:'ghost',size:'xs',data:{id:e.id}})}</div>
${e.unilateral?unilateralRows(e):bilateralRows(e)}
<div class="row wrap mt12">${btn('Aggiungi serie','add-set',{kind:'secondary',size:'small',icon:'plus',data:{id:e.id}})}${e.sets.length>1?btn('Rimuovi ultima','remove-set',{kind:'ghost',size:'small',data:{id:e.id}}):''}</div>
<div class="row between mt12"><span class="small" style="color:#93bfff">Recupero: ${select([30,45,60,75,90,120,150,180,240,300].map(x=>({value:x,label:x+' s'})),e.restSec,'entry-rest',{data:{entry:e.id}})}</span>${s.restTimer?.entryId===e.id&&s.restTimer.endsAt>Date.now()?`<div class="row">${ic('clock',16)} <b class="live-rest" data-rest-entry="${e.id}">${formatDuration((s.restTimer.endsAt-Date.now())/1000).slice(3)}</b>${btn('Ferma','stop-rest',{kind:'danger',size:'xs'})}</div>`:btn('Avvia timer','start-rest',{kind:'secondary',size:'small',icon:'clock',data:{id:e.id}})}</div>
${progHint?`<div class="inline-success mt12">${ic('chart',15)} ${esc(progHint)}</div>`:''}
<div class="field mt12"><label>Feedback di oggi</label><textarea class="textarea" rows="2" data-bind="entry-feedback" data-entry="${e.id}" placeholder="Tecnica, cedimento, sensazioni, cosa migliorare...">${esc(e.feedback)}</textarea></div>
<div class="exercise-actions">${btn('Collega superserie','set-superset',{kind:'ghost',size:'small',icon:'layers',data:{id:e.id}})}${btn('Sostituisci esercizio','browse-catalog',{kind:'ghost',size:'small',icon:'swap',data:{mode:'session-replace',id:e.id}})}${btn('↑','move-entry',{kind:'secondary',size:'small',data:{id:e.id,delta:-1},disabled:i===0})}${btn('↓','move-entry',{kind:'secondary',size:'small',data:{id:e.id,delta:1},disabled:i===s.entries.length-1})}${btn('Rimuovi','remove-entry',{kind:'danger',size:'small',icon:'trash',data:{id:e.id}})}</div>`:''}
</article>`;}
function progressHint(e,priorSets){const best=priorSets.filter(s=>!e.unilateral&&!s.unilateral).sort((a,b)=>num(b.reps)-num(a.reps))[0];if(best&&num(best.reps)>=num(e.targetMax)&&num(best.rir)>=num(e.targetRir))return 'Nella scorsa seduta hai raggiunto il target: valuta un aumento graduale del carico mantenendo la tecnica.';return '';}
const techniques=[{value:'normal',label:'Normale'},{value:'drop',label:'Drop set'},{value:'restpause',label:'Rest-pause'},{value:'superset',label:'Superset'}];
function bilateralRows(e){return `<table class="series-table"><thead><tr><th style="width:13%">SERIE</th><th style="width:22%">KG</th><th style="width:22%">REPS</th><th style="width:22%">RIR</th><th style="width:21%">FATTA</th></tr></thead><tbody>${e.sets.map((s,i)=>`<tr><td>${i+1}</td>${['kg','reps','rir'].map(k=>`<td><input type="number" inputmode="decimal" step="any" min="0" placeholder="–" value="${esc(s[k])}" data-bind="set-field" data-entry="${e.id}" data-set="${s.id}" data-key="${k}" aria-label="${k} serie ${i+1}"></td>`).join('')}<td><input class="check" type="checkbox" data-bind="set-field" data-entry="${e.id}" data-set="${s.id}" data-key="done" ${s.done?'checked':''} aria-label="Serie ${i+1} completata"></td></tr><tr><td colspan="5"><div class="set-extras"><label>Tecnica ${select(techniques,s.technique,'set-field',{data:{entry:e.id,set:s.id,key:'technique'}})}</label><label><input type="checkbox" data-bind="set-field" data-entry="${e.id}" data-set="${s.id}" data-key="failure" ${s.failure?'checked':''}> Cedimento</label></div></td></tr>`).join('')}</tbody></table>`;}
function unilateralRows(e){return e.sets.map((s,i)=>`<div class="unilateral-set"><div class="row between mb12"><b class="small">SERIE ${i+1}</b><label class="row small"><input type="checkbox" class="check" data-bind="set-field" data-entry="${e.id}" data-set="${s.id}" data-key="done" ${s.done?'checked':''}/> Fatta</label></div><div class="side-grid"><div class="tiny muted">LATO</div><div class="tiny muted" style="text-align:center">KG</div><div class="tiny muted" style="text-align:center">REPS</div><div class="tiny muted" style="text-align:center">RIR</div>${[['SX','L'],['DX','R']].map(([label,suff])=>`<b class="tiny">${label}</b>${['kg','reps','rir'].map(k=>`<input type="number" inputmode="decimal" step="any" min="0" class="input" placeholder="–" value="${esc(s[k+suff])}" data-bind="set-field" data-entry="${e.id}" data-set="${s.id}" data-key="${k+suff}" aria-label="${label} ${k} serie ${i+1}">`).join('')}`).join('')}</div><div class="set-extras mt8"><label>Tecnica ${select(techniques,s.technique,'set-field',{data:{entry:e.id,set:s.id,key:'technique'}})}</label><label><input type="checkbox" data-bind="set-field" data-entry="${e.id}" data-set="${s.id}" data-key="failure" ${s.failure?'checked':''}> Cedimento</label></div></div>`).join('');}
function finishView(){const s=state.active;if(!s){return workoutView();}const ds=s.entries.reduce((v,e)=>v+doneSets(e).length,0),tot=s.entries.reduce((v,e)=>v+e.sets.length,0);let records=workoutPRs(s);return `${head('Riepilogo allenamento','Controlla prima di salvare definitivamente.')}
<div class="card"><div class="eyebrow">${esc(gymName(s.gymId))} · ${esc(s.programName)}</div><h2 style="font-size:25px;margin:9px 0">${esc(s.dayName)}</h2><p class="sub">${dateLabel(s.startedAt)}</p><div class="stat-grid mt12">${[[formatDuration(sessionSeconds(s)),'Durata'],[`${ds} / ${tot}`,'Serie completate'],[dval(sessionVolume(s))+' kg','Volume totale'],[records.length,'Record rilevati']].map(([v,l])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-num">${v}</div></div>`).join('')}</div></div>
${tot>ds?`<div class="inline-alert mb12">${ic('info',16)} Hai ${tot-ds} serie non spuntate. Puoi tornare alla seduta o salvarla comunque come parziale.</div>`:''}
${records.length?`<div class="card"><h3 class="mb12">🏆 Record personali</h3>${records.map(r=>`<p class="small">${esc(r)}</p>`).join('')}</div>`:''}
<div class="card"><h3>Riepilogo esercizi</h3>${s.entries.map((e,i)=>`<div class="row between mt12"><div><b class="small">${i+1}. ${esc(e.name)}</b><p class="sub tiny">${doneSets(e).length} serie ${e.extra?'· Extra':''}</p></div><span class="small">${dval(volumeOf(e))} kg</span></div>`).join('')||'<p class="sub">Nessun esercizio</p>'}</div>
<div class="card"><div class="field"><label>Feedback finale (modificabile)</label><textarea class="textarea" data-bind="session-note">${esc(s.note)}</textarea></div></div>
<div class="stack">${btn('Salva e chiudi allenamento','finish-session',{full:true,icon:'check',data:{status:tot>ds?'partial':'complete'}})}${tot>ds?btn('Salva comunque come completato','finish-session',{full:true,kind:'secondary',data:{status:'complete'}}):''}${btn('Torna all’allenamento','go',{full:true,kind:'ghost',data:{to:'workout'}})}</div>`;}
function workoutPRs(s){const found=[];for(const e of s.entries){const newSets=doneSets(e);if(!newSets.length)continue;const history=exerciseHistory(state,e.exerciseId,s.gymId,'all');const before=exerciseRecords(history),now=exerciseRecords([{entry:e}]);if(now.bestKg>before.bestKg&&now.bestKg>0)found.push(`${e.name}: carico record ${dval(now.bestKg)} kg`);if(now.bestKg===before.bestKg&&now.maxRepsAtBest>before.maxRepsAtBest)found.push(`${e.name}: ${dval(now.maxRepsAtBest)} reps a ${dval(now.bestKg)} kg`);if(now.bestVolume>before.bestVolume&&now.bestVolume>0)found.push(`${e.name}: volume record ${dval(now.bestVolume)} kg`);}return found;}

function historyView(){const sorted=recentSessions();if(historySessionId){const s=sorted.find(x=>x.id===historySessionId);if(s)return `${head('Dettaglio seduta',dateLabel(s.startedAt),btn('Indietro','close-history-detail',{kind:'ghost',size:'small',icon:'back'}))}${sessionDetail(s)}`;}
const chosen=historyDate||dateKey(Date.now());const d=new Date(chosen+'T12:00:00');const year=d.getFullYear(),month=d.getMonth();const start=new Date(year,month,1);const offset=(start.getDay()+6)%7;const daysCount=new Date(year,month+1,0).getDate();const dayKeys=new Map();for(const s of sorted){const key=dateKey(s.startedAt);dayKeys.set(key,[...(dayKeys.get(key)||[]),s]);}
const cells=[...Array(offset)].map(()=>'<div class="cal-cell empty"></div>');for(let i=1;i<=daysCount;i++){const key=dateKey(new Date(year,month,i).getTime()),ss=dayKeys.get(key)||[];cells.push(`<button type="button" class="cal-cell ${ss.length?'session':''} ${key===dateKey(Date.now())?'today':''}" data-action="select-history-date" data-day="${key}" ${key===chosen?'style="outline:2px solid #83b7ff"':''}><span>${i}</span>${ss.length?'<span class="cal-dot"></span>':''}</button>`);}
const chosenSessions=sorted.filter(s=>dateKey(s.startedAt)===chosen);return `${head('Storico','Il tuo diario, senza cancellare il passato.')}
<div class="card"><div class="row between mb16">${btn('‹','history-month',{kind:'secondary',size:'small',data:{delta:-1}})}<h2>${new Intl.DateTimeFormat('it-IT',{month:'long',year:'numeric'}).format(d)}</h2>${btn('›','history-month',{kind:'secondary',size:'small',data:{delta:1}})}</div><div class="calendar">${['L','M','M','G','V','S','D'].map(x=>`<div class="cal-label">${x}</div>`).join('')}${cells.join('')}</div><p class="sub tiny mt12">Tocca un giorno evidenziato per vedere le sedute.</p></div>
<div class="section-head"><h2>${esc(dateLabel(d.getTime()))}</h2>${tag(`${chosenSessions.length} sedute`)}</div>
${chosenSessions.length?chosenSessions.map(s=>sessionListCard(s)).join(''):'<div class="card"><p class="sub">Nessun allenamento registrato in questo giorno.</p></div>'}
<div class="section-head"><h2>Tutte le sedute</h2>${tag(`${sorted.length} totali`)}</div>${sorted.slice(0,50).map(s=>sessionListCard(s)).join('')||emptyBlock('📖','Storico vuoto','Completa la prima seduta e la troverai qui.')}`;}
function sessionListCard(s){return `<div class="card"><div class="row between"><div><b>${esc(s.dayName)}</b><p class="sub">${esc(gymName(s.gymId))} · ${esc(dateLabel(s.startedAt))}</p></div>${tag(s.status==='partial'?'Parziale':'Completata',s.status==='partial'?'warn':'success')}</div><div class="row wrap mt12"><span class="pill">${ic('clock',13)} ${formatDuration(sessionSeconds(s))}</span><span class="pill">${s.entries.length} esercizi</span><span class="pill">${s.entries.reduce((x,e)=>x+doneSets(e).length,0)} serie</span></div><div class="mt12">${btn('Apri dettagli','session-detail',{kind:'secondary',size:'small',data:{id:s.id}})}</div></div>`;}
function sessionDetail(s){return `<div class="card"><div class="eyebrow">${esc(gymName(s.gymId))}</div><h2 style="margin:9px 0">${esc(s.dayName)}</h2><p class="sub">${esc(s.programName)} · ${esc(s.focus||'')}</p><div class="stat-grid mt12"><div class="stat"><div class="stat-label">Durata</div><div class="stat-num">${formatDuration(sessionSeconds(s))}</div></div><div class="stat"><div class="stat-label">Volume</div><div class="stat-num">${dval(sessionVolume(s))} kg</div></div></div>${s.note?`<div class="divider"></div><div class="eyebrow">Feedback generale</div><p class="feedback-copy">${esc(s.note)}</p>`:''}</div>
${s.entries.map((e,i)=>`<div class="card"><div class="row between"><h3>${i+1}. ${esc(e.name)}</h3>${e.extra?tag('EXTRA','highlight'):''}</div>${e.originalName?`<p class="sub">Sostituisce: ${esc(e.originalName)}</p>`:''}<table class="prev-table">${doneSets(e).map((set,j)=>`<tr><td>Serie ${j+1}</td>${e.unilateral?`<td>SX: ${esc(set.kgL)} kg × ${esc(set.repsL)}</td><td>DX: ${esc(set.kgR)} kg × ${esc(set.repsR)}</td>`:`<td>${esc(set.kg)} kg</td><td>${esc(set.reps)} rep</td><td>RIR ${esc(set.rir||'–')}</td>`}</tr>`).join('')||'<tr><td>Nessuna serie completata</td></tr>'}</table>${e.feedback?`<div class="divider"></div><span class="tiny muted">FEEDBACK</span><p class="small feedback-copy">${esc(e.feedback)}</p>`:''}</div>`).join('')}`;}
function metricFromEntry(e,kind){const done=doneSets(e);if(kind==='volume')return volumeOf(e);if(kind==='reps')return Math.max(0,...done.flatMap(s=>e.unilateral?[num(s.repsL),num(s.repsR)]:[num(s.reps)]));return Math.max(0,...done.flatMap(s=>e.unilateral?[num(s.kgL),num(s.kgR)]:[num(s.kg)]));}
function lineChart(points,{label='',unit='',minZero=true}={}){if(!points.length)return '<div class="empty sub">Nessun dato disponibile per questo filtro.</div>';const width=360,height=204,marginL=42,marginR=14,marginTop=18,marginBottom=31;const vals=points.map(p=>p.y),max=Math.max(...vals,1),min=minZero?0:Math.min(...vals),range=Math.max(1,max-min),x=i=>marginL+(width-marginL-marginR)*(points.length===1?.5:i/(points.length-1)),y=v=>marginTop+(height-marginTop-marginBottom)*(1-(v-min)/range);const path=points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p.y).toFixed(1)}`).join(' ');const area=path+` L${x(points.length-1)},${height-marginBottom} L${x(0)},${height-marginBottom} Z`;return `<div class="chart-area"><svg class="chart-svg" viewBox="0 0 360 204" role="img" aria-label="Grafico ${esc(label)} con ${points.length} rilevazioni">${[0,.25,.5,.75,1].map(t=>{const val=min+range*t;const yy=y(val);return `<path d="M${marginL} ${yy} H${width-marginR}" stroke="#33445b" stroke-width=".75" stroke-dasharray="3 4"/><text x="${marginL-8}" y="${yy+3}" text-anchor="end" font-size="10" fill="#94a8c1">${dval(val)}</text>`;}).join('')}<path d="${area}" fill="#387fee" fill-opacity=".16"/><path d="${path}" fill="none" stroke="#76acff" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.y)}" r="3.7" stroke="#d1e4ff" stroke-width="1.3" fill="#458bf7"><title>${esc(shortDate(p.at||Date.now()))}: ${dval(p.y)} ${esc(unit)}</title></circle>`).join('')}<text x="${marginL}" y="${height-10}" font-size="11" fill="#94a8c1">${shortDate(points[0].at||Date.now())}</text><text x="${width-marginR}" y="${height-10}" text-anchor="end" font-size="11" fill="#94a8c1">${shortDate(points[points.length-1].at||Date.now())}</text></svg><div class="chart-legend"><span>${esc(label)} · ${points.length} rilevazioni</span><strong>${dval(points.at(-1)?.y)} ${esc(unit)}</strong></div></div>`;}
function unilateralMetric(entry,side,metric){const arr=doneSets(entry),suffix=side==='left'?'L':'R';if(metric==='volume')return arr.reduce((v,s)=>v+num(s['kg'+suffix])*num(s['reps'+suffix]),0);const key=(metric==='reps'?'reps':'kg')+suffix;return Math.max(0,...arr.map(s=>num(s[key])));}
function dualLineChart(history,metric){const filtered=history.filter(h=>h.entry.unilateral);if(!filtered.length)return '<p class="sub">Nessuna serie unilaterale disponibile in questo periodo.</p>';const series=filtered.map(h=>({at:h.at,left:unilateralMetric(h.entry,'left',metric),right:unilateralMetric(h.entry,'right',metric)}));const w=360,h=205,l=41,r=14,top=20,bottom=29,max=Math.max(1,...series.flatMap(x=>[x.left,x.right]));const x=i=>l+(w-l-r)*(series.length===1?.5:i/(series.length-1)),y=v=>top+(h-top-bottom)*(1-v/max),path=key=>series.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p[key]).toFixed(1)}`).join(' ');return `<div class="chart-area"><svg class="chart-svg" viewBox="0 0 360 205" role="img" aria-label="Grafico dei lati sinistro e destro">${[0,.25,.5,.75,1].map(t=>{const yy=y(max*t);return `<path d="M${l} ${yy} H${w-r}" stroke="#34465f" stroke-dasharray="3 3" stroke-width=".7"/><text x="${l-7}" y="${yy+3}" text-anchor="end" fill="#9eb2cb" font-size="10">${dval(max*t)}</text>`;}).join('')}<path d="${path('left')}" fill="none" stroke="#57a9ff" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/><path d="${path('right')}" fill="none" stroke="#b581ff" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>${series.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.left)}" r="3" fill="#57a9ff"/><circle cx="${x(i)}" cy="${y(p.right)}" r="3" fill="#b581ff"/>`).join('')}<text x="${l}" y="${h-8}" fill="#9eb2cb" font-size="10">${shortDate(series[0].at)}</text><text x="${w-r}" y="${h-8}" text-anchor="end" fill="#9eb2cb" font-size="10">${shortDate(series.at(-1).at)}</text></svg><div class="row between small mt8"><span style="color:#79bdff">● Sinistra: <b>${dval(series.at(-1).left)}</b></span><span style="color:#c0a0ff">● Destra: <b>${dval(series.at(-1).right)}</b></span></div></div>`;}
function exerciseRecords(events){const series=events.flatMap(({entry})=>doneSets(entry).flatMap(s=>entry.unilateral?[{kg:num(s.kgL),reps:num(s.repsL)},{kg:num(s.kgR),reps:num(s.repsR)}]:[{kg:num(s.kg),reps:num(s.reps)}]));const bestKg=Math.max(0,...series.map(s=>s.kg));const maxRepsAtBest=Math.max(0,...series.filter(s=>s.kg===bestKg).map(s=>s.reps));const bestVolume=Math.max(0,...events.map(({entry})=>volumeOf(entry)));return {bestKg,maxRepsAtBest,bestVolume};}
function progressView(){const all=exerciseOptions().filter(ex=>state.sessions.some(s=>s.entries?.some(e=>e.exerciseId===ex.id&&doneSets(e).length)));if(!progressExercise||!all.some(e=>e.id===progressExercise))progressExercise=all[0]?.id||null;
const gym=progressGym==='current'?state.gymId:progressGym;const history=progressExercise?exerciseHistory(state,progressExercise,gym,progressPeriod):[];const points=history.map(({entry,at})=>({at,y:metricFromEntry(entry,progressMetric)}));const first=points[0]?.y||0,last=points.at(-1)?.y||0,diff=first?((last/first-1)*100):0;const recents=recentSessions();const mean=recents.length?recents.reduce((v,s)=>v+sessionSeconds(s),0)/recents.length:0;return `${head('I tuoi progressi','Dati reali da ogni serie completata.')}
${!all.length?emptyBlock('📈','I grafici si riempiranno da soli','Completa una seduta e REPz inizierà a costruire il tuo storico delle prestazioni.'):
`<div class="card"><div class="field"><label>Esercizio</label>${select(all.map(e=>({value:e.id,label:e.name})),progressExercise,'progress-exercise')}</div><div class="field mt12"><label>Palestra</label>${select([{value:'current',label:'Palestra attiva: '+gymName(state.gymId)},{value:'all',label:'Tutte le palestre'},...state.gyms.filter(g=>g.id!==state.gymId).map(g=>({value:g.id,label:g.name}))],progressGym,'progress-gym')}</div><div class="field mt12"><label>Periodo</label>${select([{value:'30',label:'Ultimi 30 giorni'},{value:'90',label:'Ultimi 90 giorni'},{value:'180',label:'Ultimi 180 giorni'},{value:'all',label:'Tutto lo storico'}],progressPeriod,'progress-period')}</div><div class="tab-pills mt12">${[['weight','Carico'],['reps','Ripetizioni'],['volume','Volume']].map(([k,n])=>btn(n,'metric',{kind:k===progressMetric?'':'secondary',size:'small',data:{id:k}})).join('')}</div>${lineChart(points,{label:progressMetric==='weight'?'Carico massimo':progressMetric==='reps'?'Ripetizioni massime':'Volume per esecuzione',unit:progressMetric==='reps'?'rep':'kg'})}
<div class="stat-grid mt12"><div class="stat"><div class="stat-label">Ultimo valore</div><div class="stat-num">${dval(last)} ${progressMetric==='reps'?'rep':'kg'}</div></div><div class="stat"><div class="stat-label">Variazione periodo</div><div class="stat-num" style="color:${diff>=0?'#83efb7':'#ffb5b5'}">${diff>=0?'+':''}${dval(diff)}%</div></div></div>${gym==='all'?'<p class="sub tiny mt12">Attenzione: stai visualizzando palestre diverse. Alcune macchine possono avere resistenze non confrontabili.</p>':''}</div>
${history.some(h=>h.entry.unilateral)?`<div class="card"><h3>Confronto SX / DX</h3><p class="sub tiny mt8">Andamento distinto dei due lati (${progressMetric==='reps'?'ripetizioni':progressMetric==='volume'?'volume':'carico'}).</p>${dualLineChart(history,progressMetric)}</div>`:''}`}

<div class="section-head"><h2>Statistiche generali</h2></div><div class="stat-grid"><div class="stat"><div class="stat-label">Allenamenti registrati</div><div class="stat-num">${recents.length}</div></div><div class="stat"><div class="stat-label">Durata media</div><div class="stat-num">${formatDuration(mean).slice(0,5)}</div></div><div class="stat"><div class="stat-label">Serie totali</div><div class="stat-num">${recents.reduce((v,s)=>v+s.entries.reduce((z,e)=>z+doneSets(e).length,0),0)}</div></div><div class="stat"><div class="stat-label">Volume registrato</div><div class="stat-num">${dval(recents.reduce((v,s)=>v+sessionVolume(s),0))} kg</div></div></div>
<div class="section-head"><h2>Record personali</h2></div>${all.length?`<div class="card">${all.slice(0,40).map(ex=>{const events=exerciseHistory(state,ex.id,'all','all');const rec=exerciseRecords(events);return `<div class="metric-row" style="display:block"><b class="small">${esc(ex.name)}</b><div class="pills mt8"><span class="pill">${dval(rec.bestKg)} kg massimo</span><span class="pill">${dval(rec.maxRepsAtBest)} rep con ${dval(rec.bestKg)} kg</span><span class="pill">${dval(rec.bestVolume)} kg volume</span></div></div>`;}).join('')}<p class="sub tiny">I record massimi sono informativi; i carichi delle macchine di palestre diverse potrebbero non essere confrontabili.</p></div>`:'<div class="card"><p class="sub">Non ci sono record da mostrare.</p></div>'}`;}

function checkupStats(){const cutoff=musclePeriod==='all'?0:Date.now()-num(musclePeriod)*864e5;const sessions=state.sessions.filter(s=>s.startedAt>=cutoff&&(muscleGym==='all'||s.gymId===muscleGym));const direct=Object.fromEntries(MUSCLES.map(m=>[m[0],0]));const indirect=Object.fromEntries(MUSCLES.map(m=>[m[0],0]));const perMuscle=Object.fromEntries(MUSCLES.map(m=>[m[0],[]]));const dates=Object.fromEntries(MUSCLES.map(m=>[m[0],new Set()]));for(const s of sessions){for(const e of s.entries){const ex=$ex(e.exerciseId),n=doneSets(e).length;if(!n||!ex)continue;const primary=ex.primary;if(primary in direct){direct[primary]+=n;perMuscle[primary].push({exercise:e,session:s,sets:n});dates[primary].add(dateKey(s.startedAt));}for(const sec of ex.secondary||[])if(sec in indirect)indirect[sec]+=n;}}return {sessions,direct,indirect,perMuscle,dates};}
function checkupView(){const stats=checkupStats(),{direct,indirect}=stats;const max=Math.max(1,...Object.values(direct));const focus=muscleFocus||'petto';const chosen=MUSCLES.find(x=>x[0]===focus)||MUSCLES[0];const directSum=Object.values(direct).reduce((a,b)=>a+b,0);const upper=MUSCLES.filter(x=>x[2]==='upper').reduce((a,x)=>a+direct[x[0]],0),lower=MUSCLES.filter(x=>x[2]==='lower').reduce((a,x)=>a+direct[x[0]],0);const lastForMuscle=[...stats.perMuscle[focus]].sort((a,b)=>b.session.startedAt-a.session.startedAt)[0];const selectedSets=stats.perMuscle[focus].flatMap(p=>doneSets(p.exercise).map(set=>({set,unilateral:p.exercise.unilateral})));const rirValues=selectedSets.flatMap(({set,unilateral})=>unilateral?[set.rirL,set.rirR]:[set.rir]).filter(x=>x!==''&&x!==null&&x!==undefined).map(num);const meanRIR=rirValues.length?dval(rirValues.reduce((a,b)=>a+b,0)/rirValues.length):'–';const recent7=stats.perMuscle[focus].filter(x=>x.session.startedAt>=Date.now()-7*864e5).reduce((a,b)=>a+b.sets,0);const weekGroups=Array.from({length:4},(_,i)=>({week:i,from:Date.now()-(4-i)*7*864e5,to:Date.now()-(3-i)*7*864e5,sets:0}));for(const p of stats.perMuscle[focus]){const g=weekGroups.find(g=>p.session.startedAt>=g.from&&p.session.startedAt<g.to);if(g)g.sets+=p.sets;}const nonzero=MUSCLES.filter(m=>direct[m[0]]>0).length;const highMuscles=MUSCLES.filter(m=>direct[m[0]]>=num(state.settings.muscleHigh));const lowMuscles=MUSCLES.filter(m=>direct[m[0]]>0&&direct[m[0]]<=num(state.settings.muscleLow));return `${head('Check-up muscolare','La tua mappa del lavoro muscolare.')}
<div class="tab-pills">${[['7','7 giorni'],['28','28 giorni'],['90','90 giorni'],['all','Totale']].map(([id,t])=>btn(t,'muscle-period',{kind:musclePeriod===id?'':'secondary',size:'small',data:{id}})).join('')}</div>
<div class="card flat"><div class="row between"><div class="eyebrow">PALESTRA</div><span class="pill">${stats.sessions.length} sedute</span></div><div class="mt8">${select([{value:'all',label:'Tutte le palestre'},...state.gyms.map(g=>({value:g.id,label:g.name}))],muscleGym,'muscle-gym')}</div></div>
<div class="anatomy-card"><div class="row between mb12"><div><h2>Muscoli allenati</h2><p class="sub tiny">Tocca un distretto per esplorarlo</p></div>${tag(`${nonzero} distretti`,'highlight')}</div>${anatomySVG(direct,num(state.settings.muscleLow),num(state.settings.muscleHigh))}<div class="legend"><span><i class="legend-dot" style="background:#526071"></i>Assente</span><span><i class="legend-dot" style="background:#44bce8"></i>Basso</span><span><i class="legend-dot" style="background:#5279fc"></i>Medio</span><span><i class="legend-dot" style="background:#a265ff"></i>Alto</span></div></div>
<div class="section-head"><h2>Serie per distretto</h2><span class="sub tiny">Solo serie dirette</span></div><div class="muscle-rows">${MUSCLES.map(([id,name])=>`<button class="muscle-item" data-action="focus-muscle" data-id="${id}" style="${focus===id?'border-color:#68a5ff;background:#213d62':''}"><span>${esc(name)}</span><b>${direct[id]}</b></button>`).join('')}</div>
<div class="section-head"><h2>Dettaglio muscolare</h2></div><div class="muscle-info"><div class="row between"><div><div class="eyebrow">DISTRETTO SELEZIONATO</div><h2 style="font-size:23px;margin-top:8px">${esc(chosen[1])}</h2></div><div class="icon-circle">${ic('activity',22)}</div></div><div class="stat-grid mt12"><div class="stat"><div class="stat-label">Serie dirette</div><div class="stat-num">${direct[focus]||0}</div></div><div class="stat"><div class="stat-label">Coinvolgimenti secondari*</div><div class="stat-num">${indirect[focus]||0}</div></div><div class="stat"><div class="stat-label">Giorni allenati</div><div class="stat-num">${stats.dates[focus]?.size||0}</div></div><div class="stat"><div class="stat-label">Ultima volta</div><div class="stat-num" style="font-size:16px">${lastForMuscle?shortDate(lastForMuscle.session.startedAt):'–'}</div></div></div><div class="stat-grid mt12"><div class="stat"><div class="stat-label">RIR medio registrato</div><div class="stat-num">${selectedSets.some(({set,unilateral})=>unilateral?(set.rirL!==''||set.rirR!==''):(set.rir!==''))?meanRIR:'–'}</div></div><div class="stat"><div class="stat-label">Serie negli ultimi 7 giorni</div><div class="stat-num">${recent7}</div></div></div><p class="sub tiny mt12">*Serie di altri esercizi che coinvolgono questo muscolo; non equivalgono a serie dirette aggiuntive. Il RIR è una media dei valori che hai inserito.</p></div>
<div class="card"><h3 class="mb12">Esercizi che hanno contribuito</h3>${(()=>{const map=new Map();for(const p of stats.perMuscle[focus]){const key=p.exercise.exerciseId;map.set(key,(map.get(key)||0)+p.sets);}return [...map.entries()].sort((a,b)=>b[1]-a[1]).map(([id,sets])=>`<div class="metric-row"><span class="grow">${esc($ex(id)?.name||id)}</span><div class="progress-track" style="max-width:90px"><div class="progress-fill" style="width:${100*sets/Math.max(1,direct[focus])}%"></div></div><b>${sets}</b></div>`).join('')||'<p class="sub">Nessuna esecuzione diretta registrata.</p>';})()}</div>
<div class="card"><h3>Andamento ultime quattro settimane</h3><div class="mt12">${lineChart(weekGroups.map(g=>({at:g.from,y:g.sets})),{label:'Serie dirette per settimana',unit:'serie'})}</div></div>
<div class="section-head"><h2>Bilanciamento</h2></div><div class="card"><div class="row between"><span class="small">Parte superiore</span><b>${upper} serie</b></div><div class="progress-track mt8"><div class="progress-fill" style="width:${upper/(upper+lower||1)*100}%"></div></div><div class="row between mt12"><span class="small">Parte inferiore</span><b>${lower} serie</b></div><div class="progress-track mt8"><div class="progress-fill" style="width:${lower/(upper+lower||1)*100}%;background:#a265ff"></div></div><p class="sub tiny mt12">Il bilanciamento è descrittivo, non un voto di qualità dell'allenamento. Le serie per addome/lombari sono mostrate a parte.</p></div>
<div class="section-head"><h2>Analisi automatica</h2></div><div class="card"><div class="stack gap-lg">${stats.sessions.length===0?'<p class="sub">Completa almeno un allenamento per visualizzare le prime analisi.</p>':`<div class="row start"><span style="color:#8dbbff">${ic('chart',19)}</span><p class="small">Nel periodo selezionato hai registrato <b>${directSum} serie dirette</b>, distribuite tra ${nonzero} distretti.</p></div>${highMuscles.length?`<div class="row start"><span style="color:#a97efc">${ic('activity',19)}</span><p class="small">Volume relativamente alto per: <b>${highMuscles.map(x=>x[1]).join(', ')}</b>.</p></div>`:''}${lowMuscles.length?`<div class="row start"><span style="color:#73dafa">${ic('info',19)}</span><p class="small">Volume relativamente basso per: <b>${lowMuscles.map(x=>x[1]).join(', ')}</b>. Non è automaticamente un problema: dipende dai tuoi obiettivi.</p></div>`:''}`}</div></div>
<p class="footer-note">I colori rappresentano volume di allenamento registrato, non recupero fisiologico o diagnosi mediche.</p>`;}
function settingsView(){return `${head('Impostazioni','Personalizza REPz e proteggi i tuoi dati.')}
<div class="section-head"><h2>Gestisci palestre</h2>${btn('Aggiungi','add-gym',{kind:'secondary',size:'small',icon:'plus'})}</div>
<div class="card">${state.gyms.map(g=>`<div class="row between mb12"><div class="grow">${field('Nome palestra',g.name,'gym-name',{data:{id:g.id}})}</div>${state.gymId===g.id?tag('Attiva','highlight'):btn('Seleziona','choose-gym',{kind:'secondary',size:'small',data:{id:g.id}})}</div>`).join('')}<p class="sub tiny">I nomi sono liberi; puoi avere palestre con attrezzature differenti.</p></div>
<div class="section-head"><h2>Catalogo personale</h2></div><div class="card"><p class="sub">Gli esercizi creati da te rimangono disponibili per le prossime schede. Puoi correggerne nome e classificazione.</p>${state.customExercises.length?state.customExercises.map(ex=>`<div class="row between mt12"><div class="grow"><b class="small">${esc(ex.name)}</b><p class="tiny muted">${esc(muscleName(ex.primary))}</p></div>${btn('Modifica','edit-custom',{kind:'secondary',size:'small',icon:'edit',data:{id:ex.id}})}</div>`).join(''):'<p class="sub tiny mt12">Non hai ancora creato esercizi personalizzati.</p>'}</div>
<div class="section-head"><h2>Check-up muscolare</h2></div><div class="card"><p class="sub">Soglie illustrative per la colorazione delle serie dirette nel periodo selezionato.</p><div class="stat-grid mt12">${field('Basso fino a (serie)',state.settings.muscleLow,'settings',{type:'number',min:0,data:{key:'muscleLow'}})}${field('Alto da (serie)',state.settings.muscleHigh,'settings',{type:'number',min:1,data:{key:'muscleHigh'}})}</div></div>
<div class="section-head"><h2>Timer</h2></div><div class="card"><div class="field"><label>Recupero predefinito per nuovi esercizi</label>${select([30,45,60,75,90,120,150,180,240,300].map(n=>({label:n+' secondi',value:n})),state.settings.restDefault,'settings',{data:{key:'restDefault'}})}</div><p class="sub tiny mt12">Il timer recupero parte solo quando premi Avvia, mai quando spunti una serie.</p></div>
<div class="section-head"><h2>Backup e dati</h2></div><div class="card"><p class="sub">Le sessioni sono salvate localmente. Esporta periodicamente un backup, perché la cancellazione dei dati di Safari può eliminarle.</p><div class="stack mt12">${btn('Scarica backup completo (.json)','export-json',{full:true,icon:'download'})}${btn('Esporta storico (.csv)','export-csv',{kind:'secondary',full:true,icon:'file'})}<label class="btn ghost full" for="file-import">${ic('upload',16)} Importa backup (.json)</label><input type="file" id="file-import" accept=".json,application/json" style="display:none"/></div></div>
<div class="section-head"><h2>Installazione iPhone</h2></div><div class="card"><p class="small">Una volta pubblicata l'app su un sito HTTPS, aprila in Safari, tocca <b>Condividi</b> e scegli <b>Aggiungi alla schermata Home</b>.</p><p class="sub tiny mt8">Per l'utilizzo offline apri almeno una volta l'app con connessione e attendi la memorizzazione dei file. L'Apple Watch richiederebbe in futuro una componente watchOS nativa.</p></div>
<div class="section-head"><h2>Informazioni</h2></div><div class="card"><div class="row between"><b>REPz</b>${tag('v1.0')}</div><p class="sub mt12">Train. Track. Progress. Nessun account, nessun abbonamento, nessun tracciamento pubblicitario.</p></div>`;}
function modalView(){if(!modal)return '';let body='';const textInput=(key,label,placeholder='',type='text')=>field(label,modal.fields?.[key]??'','modal-text',{placeholder,type,data:{key}});
if(['new-program','rename-program','new-day','edit-day','add-gym','superset'].includes(modal.type)){
const titles={'new-program':'Crea una scheda','rename-program':'Rinomina scheda','new-day':'Aggiungi un giorno','edit-day':'Modifica giorno','add-gym':'Aggiungi palestra','superset':'Collega una superserie'};
body=`<h2>${titles[modal.type]}</h2><div class="stack mt12">${textInput('name',modal.type==='superset'?'Gruppo superserie (es. A)':modal.type==='add-gym'?'Nome della palestra':modal.type.includes('day')?'Nome del giorno':'Nome del programma',modal.type.includes('day')?'Giorno 1':'La mia scheda')}${modal.type.includes('day')?textInput('focus','Distretti muscolari (facoltativo)','Es. Petto, spalle e tricipiti'):''}${btn('Salva','modal-save',{full:true,icon:'check'})}</div>`;
}else if(modal.type==='catalog'){
body=`<h2>${modal.mode==='session-replace'||modal.mode==='plan-replace'?'Sostituisci esercizio':'Aggiungi esercizio'}</h2><p class="sub">Scegli dal catalogo oppure crea una variante personalizzata.</p><div class="mt12">${field('Cerca per nome o variante',modal.query||'','catalog-search',{placeholder:'Es. panca Scott, lat machine, squat'})}</div><div class="row mt12 mb12">${btn('Cerca nel catalogo','catalog-list',{kind:!modal.custom?'':'secondary',size:'small'})}${btn('Esercizio personalizzato','catalog-custom',{kind:modal.custom?'':'secondary',size:'small',icon:'plus'})}</div>${modal.custom?`<div class="stack">${textInput('name','Nome esercizio','Scrivi il nome che preferisci')}<div class="field"><label>Distretto muscolare principale</label>${select(muscleOptions(),modal.fields.primary,'modal-primary')}</div><div class="field"><label>Muscoli secondari (facoltativi)</label><div class="row wrap">${MUSCLES.filter(m=>m[0]!==modal.fields.primary).map(([id,name])=>`<label class="pill" style="cursor:pointer"><input type="checkbox" data-bind="modal-secondary" data-key="${id}" ${(modal.fields.secondary||[]).includes(id)?'checked':''}> ${esc(name)}</label>`).join('')}</div></div>${btn('Crea e usa esercizio','create-custom',{full:true,icon:'plus'})}</div>`:
`<div class="search-results" id="catalog-results">${catalogResultHTML()}</div>`}
${modal.mode==='session-replace'?`<div class="mt12"><label class="row small"><input type="checkbox" data-bind="catalog-permanent" ${modal.permanent?'checked':''}/> Salva la sostituzione anche nella scheda permanente</label></div>`:''}`;
}else if(modal.type==='edit-custom'){
body=`<h2>Modifica esercizio personalizzato</h2><div class="stack mt12">${textInput('name','Nome esercizio','Nome personalizzato')}<div class="field"><label>Muscolo principale</label>${select(muscleOptions(),modal.fields.primary,'modal-primary')}</div><div class="field"><label>Muscoli secondari</label><div class="row wrap">${MUSCLES.filter(m=>m[0]!==modal.fields.primary).map(([id,name])=>`<label class="pill"><input type="checkbox" data-bind="modal-secondary" data-key="${id}" ${(modal.fields.secondary||[]).includes(id)?'checked':''}> ${esc(name)}</label>`).join('')}</div></div>${btn('Salva esercizio','modal-save',{full:true,icon:'check'})}</div>`;
}else if(modal.type==='config'){
const a=modal.temp;body=`<h2>Configura esercizio</h2><p class="sub">${esc($ex(a.exerciseId)?.name||'Esercizio')}</p><div class="stack mt12">${field('Nome visualizzato (facoltativo)',a.label||'','assignment-field',{placeholder:'Es. Scott EZ Palestra 2',data:{key:'label'}})}${field('Numero serie',a.setCount,'assignment-field',{type:'number',min:1,data:{key:'setCount'}})}<div class="stat-grid">${field('Reps minime',a.targetMin,'assignment-field',{type:'number',min:1,data:{key:'targetMin'}})}${field('Reps massime',a.targetMax,'assignment-field',{type:'number',min:1,data:{key:'targetMax'}})}${field('RIR obiettivo',a.targetRir,'assignment-field',{type:'number',min:0,data:{key:'targetRir'}})}${field('Recupero (secondi)',a.restSec,'assignment-field',{type:'number',min:0,data:{key:'restSec'}})}</div><label class="row"><input class="check" type="checkbox" data-bind="assignment-unilateral" ${a.unilateral?'checked':''}/> Esecuzione unilaterale (SX / DX)</label>${field('Gruppo superserie (facoltativo)',a.supersetGroup||'','assignment-field',{placeholder:'Es. A: esercizi con lo stesso gruppo sono collegati',data:{key:'supersetGroup'}})}${btn('Salva configurazione','modal-save',{full:true,icon:'check'})}</div>`;
}else if(modal.type==='copy-day'){
const gymOpts=state.gyms.filter(g=>g.id!==state.gymId);body=`<h2>Copia esercizi da un'altra palestra</h2><p class="sub">Copierai gli esercizi del giorno selezionato nella palestra ${esc(gymName(state.gymId))}. Gli storici rimarranno separati.</p>${gymOpts.length?`<div class="field mt12"><label>Palestra di origine</label>${select(gymOpts.map(g=>({value:g.id,label:g.name})),modal.fields.source,'modal-source')}</div><div class="inline-alert mt12">Gli eventuali esercizi già configurati per questa palestra saranno sostituiti.</div>${btn('Copia scheda del giorno','modal-save',{full:true,icon:'layers'})}`:'<p class="sub">Aggiungi prima un’altra palestra.</p>'}`;
}else if(modal.type==='confirm'){
body=`<h2>${esc(modal.title||'Conferma')}</h2><p class="sub mt12">${esc(modal.message||'Confermi questa operazione?')}</p><div class="row mt12">${btn('Conferma','confirm-yes',{kind:'danger',full:true})}${btn('Annulla','modal-close',{kind:'secondary',full:true})}</div>`;
}
return `<div class="overlay" role="presentation" data-action="overlay-close"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(modal.type)}"><div class="modal-head"><span class="eyebrow">REPz</span>${btn(ic('close',18),'modal-close',{kind:'ghost',size:'small'})}</div>${body}</section></div>`;}
function catalogResultHTML(){if(!modal||modal.type!=='catalog')return '';const exs=matchExercises(exerciseOptions(),modal.query||'');return exs.length?exs.map(e=>`<button class="search-result" data-action="select-exercise" data-id="${e.id}"><b>${esc(e.name)}</b><p class="sub tiny">${esc(muscleName(e.primary))} · ${esc(e.equipment||'Personalizzato')} ${e.custom?'· Personalizzato':''}</p></button>`).join(''):'<div class="empty"><p class="sub">Nessun esercizio corrispondente. Puoi crearlo manualmente.</p></div>';}
function openModal(type,extra={}){modal={type,fields:{},...extra};redraw();setTimeout(()=>{const el=app.querySelector('.modal .input');if(el)el.focus();},70);}
function modalSave(){if(!modal)return;const m=modal,p=$program(),d=$day();if(['new-program','rename-program','new-day','edit-day','add-gym','superset'].includes(m.type)){
const name=(m.fields.name||'').trim();if(!name&&m.type!=='superset'){toast('Inserisci un nome.');return;}if(m.type==='superset'){const e=$entry(m.id);if(e)e.supersetGroup=name;}if(m.type==='new-program'){const v={id:uid('prog'),name,archived:false,days:[],nextDayId:null};state.programs.push(v);state.programId=v.id;selectedDay=null;}
if(m.type==='rename-program'&&p)p.name=name;
if(m.type==='new-day'&&p){const newDay={id:uid('day'),name,focus:(m.fields.focus||'').trim(),byGym:{}};p.days.push(newDay);if(!p.nextDayId)p.nextDayId=newDay.id;selectedDay=newDay.id;}
if(m.type==='edit-day'&&d){d.name=name;d.focus=(m.fields.focus||'').trim();}
if(m.type==='add-gym'){const id=uid('gym');state.gyms.push({id,name});state.gymId=id;}
}else if(m.type==='edit-custom'){
const ex=state.customExercises.find(x=>x.id===m.id);if(!ex)return;const name=(m.fields.name||'').trim();if(!name){toast('Inserisci il nome.');return;}ex.name=name;ex.primary=m.fields.primary;ex.secondary=(m.fields.secondary||[]).filter(x=>x!==ex.primary);
}else if(m.type==='config'){
const a=assignments(d).find(x=>x.id===m.temp.id);if(!a){toast('Esercizio non trovato.');return;}const vals=m.temp;if(num(vals.setCount)<1||num(vals.targetMax)<num(vals.targetMin)){toast('Controlla serie e intervallo ripetizioni.');return;}
Object.assign(a,{setCount:Math.max(1,Math.min(30,Math.floor(num(vals.setCount)))),targetMin:num(vals.targetMin),targetMax:num(vals.targetMax),targetRir:num(vals.targetRir),restSec:num(vals.restSec),unilateral:!!vals.unilateral,supersetGroup:String(vals.supersetGroup||''),label:String(vals.label||'').trim()});
}else if(m.type==='copy-day'){
if(!d||!m.fields.source)return;d.byGym=d.byGym||{};d.byGym[state.gymId]=(d.byGym[m.fields.source]||[]).map(a=>({...structuredClone(a),id:uid('assign')}));
}else return;
modal=null;persist();redraw();toast('Salvato.');}
function selectedExercise(id){const ex=$ex(id),m=modal;if(!ex||!m)return;const p=$program(),d=$day();if(m.mode==='plan-add'){d.byGym=d.byGym||{};if(!d.byGym[state.gymId])d.byGym[state.gymId]=[];d.byGym[state.gymId].push({id:uid('assign'),exerciseId:ex.id,setCount:3,targetMin:8,targetMax:12,targetRir:2,restSec:state.settings.restDefault,unilateral:false,supersetGroup:'',label:''});}
else if(m.mode==='plan-replace'){const a=assignments(d).find(a=>a.id===m.id);if(a)a.exerciseId=ex.id;}
else if(m.mode==='session-insert'){if(!state.active)return;const newEntry=makeEntry(ex,null,true);const pos=Math.max(0,Math.min(state.active.entries.length,Number(m.index)+1));state.active.entries.splice(pos,0,newEntry);state.active.expandedId=newEntry.id;}
else if(m.mode==='session-replace'){const e=$entry(m.id);if(!e)return;if(doneSets(e).length&&!confirm('Questo esercizio ha serie già completate. Sostituendolo, i dati delle serie attuali verranno azzerati. Continuare?'))return;const originalId=e.originalId||e.exerciseId,originalName=e.originalName||e.name;const newE=makeEntry(ex,null,e.extra);Object.assign(e,{exerciseId:newE.exerciseId,name:newE.name,originalId,originalName,sets:newE.sets,feedback:'',restSec:newE.restSec,unilateral:newE.unilateral,expanded:true});
if(m.permanent&&e.plannedAssignmentId){const parentProgram=state.programs.find(x=>x.id===state.active.programId);const actualDay=parentProgram?.days.find(x=>x.id===state.active.dayId);const a=assignments(actualDay,state.active.gymId).find(x=>x.id===e.plannedAssignmentId);if(a)a.exerciseId=ex.id;}}
modal=null;persist(true);redraw();toast('Esercizio inserito e collegato allo storico.');}
const downloadFile=(content,name,type)=>{const blob=new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);};
function confirmModal(title,message,handler){openModal('confirm',{title,message,handler});}
function handleAction(action,d){const p=$program(),day=$day(),s=state.active;
switch(action){
case 'go':if(d.to==='workout'&&!s){page='workout';redraw({top:true});return;}navigate(d.to);return;
case 'choose-gym':state.gymId=d.id;persist();redraw();return;
case 'new-program':openModal('new-program',{fields:{name:''}});return;
case 'archive-program':if(p){p.archived=!p.archived;if(p.archived){const next=state.programs.find(x=>!x.archived&&x.id!==p.id);if(next){state.programId=next.id;selectedDay=null;}}persist();redraw();toast(p.archived?'Scheda archiviata. Puoi ripristinarla quando vuoi.':'Scheda ripristinata.');}return;
case 'rename-program':if(p)openModal('rename-program',{fields:{name:p.name}});return;
case 'new-day':if(p)openModal('new-day',{fields:{name:`Giorno ${p.days.length+1}`,focus:''}});return;
case 'edit-day':if(day)openModal('edit-day',{fields:{name:day.name,focus:day.focus||''}});return;
case 'choose-day':selectedDay=d.id;redraw();return;
case 'delete-program':if(p)confirmModal('Eliminare la scheda?',`La scheda "${p.name}" verrà eliminata, ma lo storico delle sedute rimarrà disponibile.`,()=>{state.programs=state.programs.filter(x=>x.id!==p.id);state.programId=state.programs[0]?.id||null;selectedDay=null;});return;
case 'delete-day':if(day)confirmModal('Eliminare il giorno?',`Il giorno "${day.name}" verrà rimosso dalla scheda. Le vecchie sedute rimarranno nello storico.`,()=>{p.days=p.days.filter(x=>x.id!==day.id);if(p.nextDayId===day.id)p.nextDayId=p.days[0]?.id||null;selectedDay=null;});return;
case 'browse-catalog':openModal('catalog',{mode:d.mode,id:d.id,index:d.index!==undefined?Number(d.index):null,permanent:false,custom:false,query:'',fields:{name:'',primary:'bicipiti',secondary:[]}});return;
case 'catalog-list':modal.custom=false;redraw();return;
case 'catalog-custom':modal.custom=true;modal.fields.name=modal.query||modal.fields.name||'';redraw();return;
case 'create-custom':{const name=modal.fields.name?.trim();if(!name){toast('Scrivi il nome dell’esercizio.');return;}const ex={id:uid('custom'),name,primary:modal.fields.primary||'bicipiti',secondary:(modal.fields.secondary||[]).filter(x=>x!==modal.fields.primary),equipment:'Personalizzato',aliases:[],custom:true};state.customExercises.push(ex);selectedExercise(ex.id);return;}
case 'select-exercise':selectedExercise(d.id);return;
case 'config-assignment':{const a=assignments(day).find(x=>x.id===d.id);if(a)openModal('config',{temp:structuredClone(a)});return;}
case 'remove-assignment':{const a=assignments(day).find(x=>x.id===d.id);if(!a)return;confirmModal('Rimuovere l’esercizio?',`Verrà tolto dalla scheda. Lo storico di "${$ex(a.exerciseId)?.name||''}" resterà salvato.`,()=>{day.byGym[state.gymId]=assignments(day).filter(x=>x.id!==a.id);});return;}
case 'move-assignment':{const list=assignments(day),i=list.findIndex(x=>x.id===d.id),j=i+Number(d.delta);if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];persist();redraw();return;}
case 'copy-day':{const g=state.gyms.find(g=>g.id!==state.gymId);openModal('copy-day',{fields:{source:g?.id||''}});return;}
case 'start-day':beginWorkout(d.id);return;
case 'toggle-entry':{const e=$entry(d.id);if(e){e.expanded=e.expanded===false?true:false;s.expandedId=e.id;persist();redraw();}return;}
case 'toggle-unilateral':{const e=$entry(d.id);if(e){e.unilateral=!e.unilateral;persist();redraw();}return;}
case 'add-set':{const e=$entry(d.id);if(e){e.sets.push(makeSet());persist();redraw();}return;}
case 'remove-set':{const e=$entry(d.id);if(!e||e.sets.length<2)return;if(e.sets.at(-1).done){confirmModal('Rimuovere la serie?', 'La serie finale è completata. Vuoi davvero eliminarla?',()=>e.sets.pop());return;}e.sets.pop();persist();redraw();return;}
case 'remove-entry':{const e=$entry(d.id);if(!e)return;confirmModal('Rimuovere esercizio dalla seduta?',`L'esercizio "${e.name}" verrà rimosso solo dalla seduta attuale.`,()=>{s.entries=s.entries.filter(x=>x.id!==e.id);});return;}
case 'move-entry':{const i=s.entries.findIndex(e=>e.id===d.id),j=i+Number(d.delta);if(j<0||j>=s.entries.length)return;[s.entries[i],s.entries[j]]=[s.entries[j],s.entries[i]];persist();redraw();return;}
case 'start-rest':{const e=$entry(d.id);if(!e)return;s.restTimer={entryId:e.id,endsAt:Date.now()+num(e.restSec)*1000};persist(true);redraw();return;}
case 'stop-rest':s.restTimer=null;persist();redraw();return;
case 'pause-session':s.pausedAt=Date.now();persist(true);redraw();return;
case 'resume-session':if(s.pausedAt){s.pausedMs+=Date.now()-s.pausedAt;s.pausedAt=null;persist(true);}redraw();return;
case 'show-finish':navigate('finish');return;
case 'finish-session':finishWorkout(d.status);return;
case 'session-detail':historySessionId=d.id;navigate('history');return;
case 'close-history-detail':historySessionId=null;redraw({top:true});return;
case 'select-history-date':historyDate=d.day;redraw();return;
case 'history-month':{const base=historyDate?new Date(historyDate+'T12:00:00'):new Date();const y=base.getFullYear(),m=base.getMonth()+Number(d.delta);historyDate=dateKey(new Date(y,m,1).getTime());redraw();return;}
case 'metric':progressMetric=d.id;redraw();return;
case 'muscle-period':musclePeriod=d.id;redraw();return;
case 'focus-muscle':muscleFocus=d.id;redraw();setTimeout(()=>document.querySelector('.muscle-info')?.scrollIntoView({behavior:'smooth',block:'center'}),20);return;
case 'set-superset':{const e=$entry(d.id);if(e)openModal('superset',{id:e.id,fields:{name:e.supersetGroup||''}});return;}
case 'edit-custom':{const ex=state.customExercises.find(x=>x.id===d.id);if(ex)openModal('edit-custom',{id:ex.id,fields:{name:ex.name,primary:ex.primary,secondary:[...ex.secondary]}});return;}
case 'add-gym':openModal('add-gym',{fields:{name:`Palestra ${state.gyms.length+1}`}});return;
case 'modal-save':modalSave();return;
case 'confirm-yes':{const h=modal?.handler;modal=null;if(h)h();persist();redraw();toast('Operazione completata.');return;}
case 'modal-close':modal=null;redraw();return;
case 'overlay-close':modal=null;redraw();return;
case 'export-json':{const filename=`REPz_backup_${dateKey(Date.now())}.json`;downloadFile(JSON.stringify({...state,backupCreatedAt:new Date().toISOString()},null,2),filename,'application/json;charset=utf-8');toast('Backup esportato. Conservalo in un posto sicuro.');return;}
case 'export-csv':downloadFile(exportCSV(state),`REPz_storico_${dateKey(Date.now())}.csv`,'text/csv;charset=utf-8');toast('Storico CSV esportato.');return;
}
}
let finishing=false;async function finishWorkout(status){const s=state.active;if(!s||finishing)return;finishing=true;const current=structuredClone(s);const end=Date.now();current.endedAt=end;if(current.pausedAt){current.pausedMs+=end-current.pausedAt;current.pausedAt=null;}current.status=status==='partial'?'partial':'complete';current.restTimer=null;const p=state.programs.find(p=>p.id===current.programId),oldNextDay=p?.nextDayId;if(p&&current.status==='complete'){const idx=p.days.findIndex(d=>d.id===current.dayId);if(idx!==-1&&p.days.length)p.nextDayId=p.days[(idx+1)%p.days.length].id;}state.sessions.push(current);state.active=null;state.updatedAt=Date.now();try{if(saveTimeout)clearTimeout(saveTimeout);await commit(structuredClone(state));backupActive(null);historySessionId=current.id;page='history';redraw({top:true});toast('Allenamento salvato nello storico.');}catch(err){state.sessions.pop();state.active=s;if(p)p.nextDayId=oldNextDay;backupActive(s,state.customExercises);redraw();toast('Salvataggio non riuscito, allenamento recuperato.');}finally{finishing=false;}}
function updateInput(el){const type=el.dataset.bind;if(!type)return;const v=el.type==='checkbox'?el.checked:el.value;let rerender=false;switch(type){
case 'modal-text':modal.fields[el.dataset.key]=v;return;
case 'modal-primary':modal.fields.primary=v;modal.fields.secondary=(modal.fields.secondary||[]).filter(x=>x!==v);redraw();return;
case 'modal-secondary':modal.fields.secondary=modal.fields.secondary||[];if(v&&!modal.fields.secondary.includes(el.dataset.key))modal.fields.secondary.push(el.dataset.key);if(!v)modal.fields.secondary=modal.fields.secondary.filter(x=>x!==el.dataset.key);return;
case 'modal-source':modal.fields.source=v;return;
case 'modal-config':return;
case 'catalog-permanent':modal.permanent=v;return;
case 'catalog-search':modal.query=v;{const results=document.getElementById('catalog-results');if(results)results.innerHTML=catalogResultHTML();}return;
case 'assignment-field':modal.temp[el.dataset.key]=v;return;
case 'assignment-unilateral':modal.temp.unilateral=v;return;
case 'program-select':state.programId=v;selectedDay=null;rerender=true;break;
case 'gym-name':{const g=state.gyms.find(x=>x.id===el.dataset.id);if(g)g.name=v||'Palestra senza nome';break;}
case 'settings':state.settings[el.dataset.key]=el.type==='number'||el.tagName==='SELECT'?num(v):v;break;
case 'session-note':if(state.active)state.active.note=v;break;
case 'entry-feedback':{const e=$entry(el.dataset.entry);if(e)e.feedback=v;break;}
case 'entry-rest':{const e=$entry(el.dataset.entry);if(e)e.restSec=num(v);break;}
case 'set-field':{const s=$set(el.dataset.entry,el.dataset.set);if(s){s[el.dataset.key]=v;if(el.dataset.key==='done')rerender=true;}break;}
case 'progress-exercise':progressExercise=v;rerender=true;break;
case 'progress-gym':progressGym=v;rerender=true;break;
case 'progress-period':progressPeriod=v;rerender=true;break;
case 'muscle-gym':muscleGym=v;rerender=true;break;
default:return;
}
persist();if(rerender)redraw();}
app.addEventListener('click',event=>{const muscle=event.target.closest('[data-muscle]');if(muscle){handleAction('focus-muscle',{id:muscle.dataset.muscle});return;}const el=event.target.closest('[data-action]');if(!el)return;if(el.dataset.action==='overlay-close'&&event.target!==el)return;event.preventDefault();handleAction(el.dataset.action,el.dataset);});
app.addEventListener('input',event=>{if(event.target.matches('[data-bind]')&&event.target.type!=='checkbox'&&event.target.tagName!=='SELECT')updateInput(event.target);});
app.addEventListener('change',event=>{if(event.target.matches('[data-bind]')&&(event.target.type==='checkbox'||event.target.tagName==='SELECT'))updateInput(event.target);});
app.addEventListener('change',async event=>{if(event.target.id!=='file-import')return;const file=event.target.files?.[0];if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.schema!==1||!Array.isArray(raw.programs)||!Array.isArray(raw.sessions))throw new Error('Formato di backup non valido');if(!confirm('Importando questo backup SOSTITUIRAI tutti i dati attualmente salvati sul dispositivo. Continuare?'))return;state=normalizeLoaded(raw);if(!state.gyms.some(g=>g.id===state.gymId))state.gymId=state.gyms[0].id;backupActive(state.active,state.customExercises);persist(true);historySessionId=null;selectedDay=null;muscleFocus=null;progressExercise=null;page=state.active?'workout':'home';redraw({top:true});toast('Backup importato correttamente.');}catch(err){toast('Impossibile importare il backup: '+err.message);}});
let lastScrollSave=0;window.addEventListener('scroll',()=>{if(!state.active||page!=='workout')return;state.active.scrollY=window.scrollY;const now=Date.now();if(now-lastScrollSave>450){lastScrollSave=now;persist();}},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state.active){backupActive(state.active,state.customExercises);if(saveTimeout){clearTimeout(saveTimeout);commit(structuredClone(state));}}});
window.addEventListener('pagehide',()=>{if(state.active)backupActive(state.active,state.customExercises);if(saveTimeout){clearTimeout(saveTimeout);commit(structuredClone(state));}});
setInterval(()=>{if(!state.active)return;for(const el of document.querySelectorAll('.live-duration'))el.textContent=formatDuration(sessionSeconds(state.active));const t=state.active.restTimer;if(t){const diff=Math.max(0,Math.ceil((t.endsAt-Date.now())/1000));for(const el of document.querySelectorAll('.live-rest')){if(el.dataset.restEntry===t.entryId)el.textContent=formatDuration(diff).slice(3);}if(diff===0){state.active.restTimer=null;persist();if(page==='workout'){redraw();toast('Recupero terminato.');}}}},1000);
async function init(){try{const saved=await loadState();state=normalizeLoaded(saved);}catch(err){console.error(err);state=initialState();toast('Archivio locale non disponibile: controlla le impostazioni di Safari.');}
const recovery=readActiveBackup();if(recovery?.active&&!state.sessions.some(s=>s.id===recovery.active.id)&&(!state.active||recovery.updatedAt>=state.active.updatedAt)){state.active=recovery.active;for(const ex of recovery.customExercises||[]){if(!state.customExercises.some(c=>c.id===ex.id))state.customExercises.push(ex);}persist(true);}if(!state.gyms.some(g=>g.id===state.gymId))state.gymId=state.gyms[0]?.id||'g1';if(state.programId&&!state.programs.some(p=>p.id===state.programId))state.programId=state.programs[0]?.id||null;page=state.active?'workout':'home';redraw({top:true});if(state.active&&state.active.scrollY>0)setTimeout(()=>window.scrollTo(0,state.active.scrollY),150);
if('serviceWorker'in navigator&&location.protocol.startsWith('http')){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Offline cache',err));}}
init();

export const __testing={getState:()=>state,getPage:()=>page,getModal:()=>modal,action:handleAction,input:updateInput,render:layout,checkupStats,beginWorkout,previousExecution:(exerciseId,gymId)=>previousExecution(state,exerciseId,gymId),reset:()=>{state=initialState();page='home';selectedDay=null;historySessionId=null;modal=null;}};
